/**
 * amfa-442 #9 (server half): assertHttpsUrls accepts only absolute https: URLs
 * for the named fields and throws a 400 validation_error naming the field.
 * Run: node --test test/*.test.mjs (from the admin-auth dir; no AWS SDK needed).
 */
import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import { assertHttpsUrls } from '../url-utils.mjs';

const BAD = ['javascript:alert(1)', 'http://evil.example/x', 'data:text/html,hi', '//evil.example/x', 'not a url', 'ftp://x', 42, {}];

const is400For = (field) => (e) =>
  e.statusCode === 400 && e.expose === true && e.type === 'validation_error' && e.field === field && e.message.startsWith(`${field}:`);

describe('assertHttpsUrls', () => {
  test('a normal https URL passes, and so does an absent or empty field', () => {
    assert.doesNotThrow(() => assertHttpsUrls({ a: 'https://ok.example/path?q=1', b: '', c: null }, ['a', 'b', 'c', 'missing']));
    assert.doesNotThrow(() => assertHttpsUrls(undefined, ['a']));
  });

  for (const bad of BAD) {
    test(`${JSON.stringify(bad)} -> 400 validation_error naming the field`, () => {
      assert.throws(() => assertHttpsUrls({ ok: 'https://ok.example', bad }, ['ok', 'bad']), is400For('bad'));
    });
  }

  test('the first failing field in list order is the one named', () => {
    assert.throws(() => assertHttpsUrls({ x: 'http://a', y: 'javascript:1' }, ['y', 'x']), is400For('y'));
  });
});
